// Generated by /ship test audit (Claude Opus 5.5) — 2026-10-15
// Value: protects=the form builder routes hand CoachingFormBuilder the version it shows (versionNumber), its draft state and the manage/publish rights from the role, return the builder itself (its PageHeader holds the page's only h1), deny a role without the route's permission before loading anything and 404 a missing form; the new-form route offers publishing only with coaching_forms.publish;
// fails_when=the [formId] route drops versionNumber (an optional prop TypeScript does not require: every form then reads v1, so a v4 draft offers "Xuất bản v1" and its dialog names the wrong earlier version), reads isDraft or a right from the wrong source (an archived version opening as an editable draft), wraps the builder in its own <main><h1> again (two h1s on the page), or loads the form for a role without coaching_forms.view;
// why_new=step 11b moves the "{name} · vN" heading from the routes into the builder header through the new versionNumber prop; the builder tests pass versionNumber directly and no test loaded either route;
// seam=the permission reader, getCoachingFormDetail and CoachingFormBuilder are mocked at their module boundaries and the returned element's props are inspected without rendering; notFound throws a marker; no_claim=does not prove get_coaching_form_detail returns the form's latest version
import type { ComponentProps, ReactElement } from "react";
import { afterEach, describe, expect, it, vi } from "vitest";

import CoachingFormDetailPage from "@/app/(app)/coaching/forms/[formId]/page";
import NewCoachingFormPage from "@/app/(app)/coaching/forms/new/page";
import { PermissionDeniedState } from "@/components/shared/permission-denied-state";
import type { CoachingFormDetail } from "@/features/coaching/coaching-form-data";
import type { CoachingFormBuilder } from "@/features/coaching/components/coaching-form-builder";

const dependencies = vi.hoisted(() => ({
  CoachingFormBuilder: vi.fn(() => null),
  getCoachingFormDetail: vi.fn(),
  getDatabasePermissions: vi.fn(),
}));

vi.mock("next/navigation", () => ({
  notFound: vi.fn(() => {
    throw new Error("NEXT_NOT_FOUND");
  }),
}));
vi.mock("@/lib/permissions/database-permissions", () => ({ getDatabasePermissions: dependencies.getDatabasePermissions }));
vi.mock("@/features/coaching/coaching-form-data", () => ({ getCoachingFormDetail: dependencies.getCoachingFormDetail }));
vi.mock("@/features/coaching/components/coaching-form-builder", () => ({
  CoachingFormBuilder: dependencies.CoachingFormBuilder,
}));

type BuilderProps = ComponentProps<typeof CoachingFormBuilder>;

afterEach(() => {
  vi.clearAllMocks();
});

const draftV4: CoachingFormDetail = {
  formId: "form-1",
  formStatus: "active",
  instructions: "Phụ huynh điền trong khoảng 3 phút.",
  name: "Phiếu tự đánh giá tháng",
  publishedAt: null,
  questions: [{ configuration: {}, description: "", required: true, title: "Con tên gì?", type: "short_text" }],
  responseCount: 0,
  title: "Con học tháng này thế nào?",
  versionId: "version-4",
  versionNumber: 4,
  versionStatus: "draft",
};

function allow(permissions: string[]) {
  dependencies.getDatabasePermissions.mockResolvedValue({ ok: true, permissions });
}

async function loadFormRoute() {
  return (await CoachingFormDetailPage({ params: Promise.resolve({ formId: "form-1" }) })) as ReactElement<
    Record<string, unknown>
  >;
}

function builderProps(element: ReactElement<Record<string, unknown>>): BuilderProps {
  // The builder itself, not a wrapper: its PageHeader renders the page's h1.
  expect(element.type).toBe(dependencies.CoachingFormBuilder);
  return element.props as unknown as BuilderProps;
}

describe("/coaching/forms/[formId] route", () => {
  it("hands the builder the version it shows, its draft state and the role's rights", async () => {
    allow(["coaching_forms.view", "coaching_forms.manage"]);
    dependencies.getCoachingFormDetail.mockResolvedValue(draftV4);

    const draft = builderProps(await loadFormRoute());
    expect(dependencies.getCoachingFormDetail).toHaveBeenCalledWith("form-1");
    expect(draft).toEqual({
      canManage: true,
      canPublish: false,
      formId: "form-1",
      formVersionId: "version-4",
      initialInstructions: "Phụ huynh điền trong khoảng 3 phút.",
      initialName: "Phiếu tự đánh giá tháng",
      initialQuestions: draftV4.questions,
      initialTitle: "Con học tháng này thế nào?",
      isDraft: true,
      versionNumber: 4,
    });

    allow(["coaching_forms.view", "coaching_forms.publish"]);
    dependencies.getCoachingFormDetail.mockResolvedValue({ ...draftV4, versionId: "version-3", versionNumber: 3, versionStatus: "published" });
    const published = builderProps(await loadFormRoute());
    expect(published).toMatchObject({ canManage: false, canPublish: true, isDraft: false, versionNumber: 3 });

    // Only a draft is editable: an archived version (the third status the table allows) stays read-only.
    dependencies.getCoachingFormDetail.mockResolvedValue({ ...draftV4, versionStatus: "archived" });
    expect(builderProps(await loadFormRoute()).isDraft).toBe(false);
  });

  it("loads nothing for a role without coaching_forms.view and answers a missing form with 404", async () => {
    allow(["coaching_forms.manage", "coaching_forms.publish"]);
    expect((await loadFormRoute()).type).toBe(PermissionDeniedState);
    dependencies.getDatabasePermissions.mockResolvedValue({ ok: false });
    expect((await loadFormRoute()).type).toBe(PermissionDeniedState);
    expect(dependencies.getCoachingFormDetail).not.toHaveBeenCalled();

    allow(["coaching_forms.view"]);
    dependencies.getCoachingFormDetail.mockResolvedValue(null);
    await expect(loadFormRoute()).rejects.toThrow("NEXT_NOT_FOUND");
  });
});

describe("/coaching/forms/new route", () => {
  it("opens an empty unsaved draft for coaching_forms.manage and offers publishing only with coaching_forms.publish", async () => {
    allow(["coaching_forms.view", "coaching_forms.manage", "coaching_forms.publish"]);
    const publisher = builderProps((await NewCoachingFormPage()) as ReactElement<Record<string, unknown>>);
    expect(publisher).toMatchObject({
      canManage: true,
      canPublish: true,
      formId: null,
      formVersionId: null,
      initialQuestions: [],
      isDraft: true,
    });
    // Never saved: the builder shows it as v1 and a new draft.
    expect(publisher.versionNumber ?? null).toBeNull();

    allow(["coaching_forms.view", "coaching_forms.manage"]);
    expect(builderProps((await NewCoachingFormPage()) as ReactElement<Record<string, unknown>>).canPublish).toBe(false);

    allow(["coaching_forms.view", "coaching_forms.publish"]);
    expect(((await NewCoachingFormPage()) as ReactElement).type).toBe(PermissionDeniedState);
  });
});
